from pathlib import Path
import json,re,shutil,html,datetime
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'modern-site'
posts={p['slug']:p for p in json.loads((ROOT/'data/content.json').read_text())}
assets=OUT/'wp-content/uploads/2018/10';assets.mkdir(parents=True,exist_ok=True)
source_assets=ROOT/'private/source/httpdocs/wp-content/uploads/2018/10'
for p in (source_assets.iterdir() if source_assets.exists() else []):
 if p.suffix.lower() in ['.jpg','.jpeg','.png','.gif','.pdf','.webp']:shutil.copy2(p,assets/p.name)
A='/wp-content/uploads/2018/10/'
NAV=[('/', 'Anasayfa'),('/about-us/','Hakkımızda'),('/urunlerimiz/','Ürünlerimiz'),('/faq/','Referanslarımız'),('/full-width/','Basından'),('/contact/','İletişim')]
